/**
 * Revealed
 * ----------
 * Joseph can no longer contain himself, and the brothers see his face, and he says: I am Joseph your brother. Stage: a great hall at midday, all the court standing back, a man weeping on his brothers' necks, the world turning over; light on the floor, and a long embrace.
 *
 * Palette 0x241a10 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joseph-kit.js.
 */

import { THREE, createScene, column, throne, house, pillar, person } from './joseph-kit.js';

const BG = 0x241a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1335417088, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x1b140c });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x17110a });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 14, 0, -15, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x2f2215, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241a10, bend: 0.02, ry: -0.07, s: 1.05 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, bend: 0.02, ry: -0.44, s: 1.14 });

    return W.finish();
}

export default { build };
